INSERT INTO li_cards (slug_base, spec_json, created_at) VALUES ('what-is-quantum-utility-and-how-is-it-different-from-quantum-advantage', '{"kicker":"PILLAR B · DICTIONARY","date":"STATUS AS OF: 2026-10-26","title_html":"What is <accent>“quantum utility”</accent> — and is it <b>advantage</b>?","bignum":"12 days","vlabel_html":"from IBM’s 2023 <b>“utility”</b> paper to the first classical match — later ≈10 s/point on <b>one laptop core</b>","rtitle":"CLAIM → FIRST CLASSICAL REPLY","panel":[{"n":"2019","text":"supremacy: IBM 2.5-day estimate, 2 days before publication"},{"n":"2023","text":"utility: tensor-network match, +12 days"},{"n":"2023","text":"laptop reply: 10 s per point, one core, +14 days"},{"n":"2026","text":"advantage: exact outputs, 37.3 min on 256 GPUs, +14 days"},{"text":"NO HEADLINE CLAIM HELD 14 DAYS WITHOUT A REPLY","gold":true}],"footnote":"raw dates and sources in the post"}', '2026-10-26T15:20:00.000Z');
INSERT INTO li_cards (slug_base, spec_json, created_at) VALUES ('prospective-2026-w44', '{"pillar": "D", "format": "scoreboard", "headline_en": "Week 44: 12 cases, 4 hits, 0 allosteric sites among them", "headline_es": "Semana 44: 12 casos, 4 aciertos, 0 sitios alostericos entre ellos", "number": "12/27 = 44.4% (95% CI 27.6-62.7%)", "subhead_en": "We audited the chemistry of all 12 answer ligands. One is an allosteric modulator. The detector missed that one.", "subhead_es": "Auditamos la quimica de los 12 ligandos-respuesta. Uno es un modulador alosterico. El detector fallo ese.", "limit_en": "Our negatives do not authorise anyone to discard a site.", "limit_es": "Nuestros negativos no autorizan a nadie a descartar un sitio.", "image": "/og/prospective-2026-w44", "content_hash": "sha256:5a15a963ac62072b881a3f9aeb433641b980c71d5e7fa8f8f58ac0daa8709ba3"}', '2026-10-26T12:24:40.000Z');
INSERT INTO li_cards (slug_base, spec_json, created_at) VALUES ('what-happened-to-cat-qubits-and-bosonic-error-correction', '{"kicker":"PILLAR E · HARDWARE","date":"STATUS AS OF: 2026-10-25","title_html":"What happened to <accent>cat qubits</accent> and bosonic error correction?","bignum":"≈44 min","vlabel_html":"<b>mean bit-flip time</b>, one cat qubit (Alice & Bob, Sep 25, 2025) — phase-flip on the same device: 0.4 µs","rtitle":"MEASURED VS PROMISED","panel":[{"n":"01","text":"Bit-flip >10 s → 430 s → ~1 h mean (2024–2025)"},{"n":"02","text":"AWS Ocelot d=5: 1.65% logical error per cycle"},{"n":"03","text":"Nord Quantique: 32 QEC rounds, 12.6% discarded"},{"n":"04","text":"Promised: 100 LQ on 758 cats, 2028–2030"},{"text":"0 LOGICAL-TO-LOGICAL GATES DEMONSTRATED","gold":true}],"footnote":"raw, reproducible data · sources in the post"}', '2026-10-25T12:30:24.294Z');
INSERT INTO li_cards (slug_base, spec_json, created_at) VALUES ('is-quantum-useful-for-weather-and-climate-forecasting', '{"kicker":"PILLAR A · FEASIBILITY VERDICT","date":"STATUS AS OF: 2026-10-23","title_html":"Is quantum useful for <accent>weather and climate</accent> forecasting?","bignum":"1e29","vlabel_html":"<b>gates</b> to invert one forecast-scale linear system — Scherer 2017 estimate, via arXiv:2210.17460","rtitle":"THE OPERATIONAL SCOREBOARD","panel":[{"n":"01","text":"IFS physics model — 9 km grid, in ops (ECMWF)"},{"n":"02","text":"AIFS ML model — ops since 2025-02, ~1/1000 energy"},{"n":"03","text":"Readout: ~1 bit per qubit (Tennie-Palmer)"},{"n":"04","text":"UTokyo multicloud: 4x MORE samples than classical MC"},{"text":"QUANTUM FORECASTS IN OPERATIONS: 0","gold":true}],"footnote":"our count, criteria declared in the post"}', '2026-10-23T12:40:00.000Z');
